from concurrent.futures import ThreadPoolExecutor

import pytest


def square(x: int) -> int:
    return x * x


def sum_squares_with_workers(xs: list[int], workers: int) -> int:
    """Sum of x*x over xs, squaring in a ThreadPoolExecutor with `workers` threads.

    The result is identical for every workers >= 1. An empty list gives 0.
    Raises ValueError if workers < 1.
    """
    if workers < 1:
        raise ValueError("workers must be >= 1")
    if not xs:
        return 0
    with ThreadPoolExecutor(max_workers=workers) as ex:
        return sum(ex.map(square, xs))


def sum_squares(xs: list[int]) -> int:
    """Sum of the squares of every element of xs, computed in parallel.

    Uses a default worker count; the result equals sum(x * x for x in xs)
    regardless of how many workers are used. An empty list gives 0.
    """
    return sum_squares_with_workers(xs, 4)


WORKER_COUNTS = [1, 2, 3, 4, 8, 64]


def test_sum_squares_basic() -> None:
    assert sum_squares([1, 2, 3]) == 14


def test_sum_squares_empty() -> None:
    assert sum_squares([]) == 0


def test_sum_squares_single() -> None:
    assert sum_squares([7]) == 49


def test_sum_squares_negatives_and_zero() -> None:
    assert sum_squares([-3, 0, 3]) == 18


def test_sum_squares_big_ints_exact() -> None:
    big = 10**20
    assert sum_squares([big, -big, 1]) == 2 * big * big + 1


def test_sum_squares_does_not_mutate_input() -> None:
    xs = [3, -1, 2]
    sum_squares(xs)
    assert xs == [3, -1, 2]


@pytest.mark.parametrize("workers", WORKER_COUNTS)
def test_same_result_at_every_worker_count(workers: int) -> None:
    xs = list(range(-500, 500))
    expected = sum(x * x for x in xs)
    assert sum_squares_with_workers(xs, workers) == expected


@pytest.mark.parametrize("workers", WORKER_COUNTS)
def test_workers_exceeding_length(workers: int) -> None:
    assert sum_squares_with_workers([2, 3], workers) == 13


@pytest.mark.parametrize("workers", WORKER_COUNTS)
def test_empty_at_every_worker_count(workers: int) -> None:
    assert sum_squares_with_workers([], workers) == 0


def test_all_worker_counts_agree() -> None:
    xs = [(i * 7919) % 1001 - 500 for i in range(2000)]
    results = {sum_squares_with_workers(xs, w) for w in WORKER_COUNTS}
    assert results == {sum(x * x for x in xs)}


def test_matches_sequential_on_large_input() -> None:
    xs = list(range(10_000))
    assert sum_squares(xs) == sum(square(x) for x in xs)


@pytest.mark.parametrize("workers", [0, -1])
def test_invalid_worker_count_raises(workers: int) -> None:
    with pytest.raises(ValueError):
        sum_squares_with_workers([1, 2, 3], workers)


def test_square_runs_in_thread_pool_compatible_way() -> None:
    # square must be a pure function usable with executor.map.
    with ThreadPoolExecutor(max_workers=2) as ex:
        assert list(ex.map(square, [1, 2, 3])) == [1, 4, 9]

